'use strict';

// MODULES //

var DATA = require( './data.json' );


// MAIN //

/**
* Returns a list of aggregate transform operations.
*
* @returns {StringArray} list of aggregate transform operations
*
* @example
* var out = aggregateOperations();
* // returns [ 'argmax', 'argmin', 'average', 'ci0', 'ci1', 'count', 'distinct', 'max', 'mean', 'median', 'min', 'missing', 'product', 'q1', 'q3', 'stderr', 'stdev', 'stdevp', 'sum', 'valid', 'values', 'variance', 'variancep' ]
*/
function aggregateOperations() {
	return DATA.slice();
}


// EXPORTS //

module.exports = aggregateOperations;
